settings.css:
body { background-color: rgba(0, 0, 0, 0); margin: 0px auto; overflow: hidden; }
/* Refresher draft scene: bans and picks laid out in the scene. */
.draft-obs { position: relative !important; display: block !important; width: 1920px !important; height: 1080px !important; padding: 0 !important; }
.obs-heroes-section, .obs-team-column, .obs-team-header, .obs-team-content, .obs-picks-container, .obs-header-bans, .obs-bans-minimap-container { display: contents !important; }
.obs-team-identity, .obs-bans-label { display: none !important; }
.obs-minimap-ban { position: absolute !important; top: 587px; width: 143px !important; height: 182px !important; margin: 0 !important; border: none !important; border-radius: 0 !important; background: none !important; box-shadow: none !important; display: flex !important; align-items: center; justify-content: center; overflow: hidden; transition: none !important; animation: none !important; }
.obs-minimap-ban.empty::after { font: 800 64px/1 Geist, 'Segoe UI', system-ui, sans-serif; color: rgba(255, 255, 255, 0.34); }
.obs-minimap-ban img { object-fit: cover !important; object-position: 50% 0%; filter: brightness(0.85); animation: refresher-reveal 0.35s ease-out; }
.obs-hero-slot { position: absolute !important; top: 848px; height: 200px !important; margin: 0 !important; border-radius: 0 !important; background: none !important; overflow: hidden !important; transition: none !important; animation: none !important; }
.obs-hero-slot img { object-fit: cover !important; object-position: 50% 0%; animation: refresher-reveal 0.35s ease-out; }
@keyframes refresher-reveal { from { opacity: 0; transform: scale(1.08); } to { opacity: 1; transform: none; } }
.obs-timer-bar { position: absolute !important; left: 20px; top: 1060px; width: 1880px !important; height: 4px !important; margin: 0 !important; }
.obs-timer-line.amber, .obs-timer-line.sapphire { background: #e4fbf3 !important; box-shadow: 0 0 8px rgba(140, 245, 210, 0.8), 0 0 20px rgba(52, 211, 166, 0.45) !important; }
.obs-minimap-ban.empty:nth-child(1)::after { content: "1"; }
.obs-minimap-ban.empty:nth-child(2)::after { content: "2"; }
.obs-minimap-ban.empty:nth-child(3)::after { content: "3"; }
